text:
{
  "title_novice": "Почему давление выравнивается долго",
  "summary": [
    {"text": "Перераспределение пластового давления после пуска скважины или смены её дебита длится долго.", "claims": ["c1"]},
    {"text": "Это связано с вязкостью: при фильтрации вязкой жидкости возникают очень большие силы сопротивления.", "claims": ["c2"]},
    {"text": "Скорость процесса зависит от проницаемости, вязкости и упругих коэффициентов жидкости и скелета пласта.", "claims": ["c3", "c4"]}
  ],
  "claims": [
    {"key": "c1", "text": "Длительность перераспределения давления во времени — характерная особенность упругого режима. Она возникает после пуска скважины или смены темпа отбора.", "kind": "observation", "unit_id": "u-475-e20d95", "page": 475, "quote": "Характерная особенность проявления упругого режима в процессе разработки нефтяных месторождений проявляется в длительности во времени процесса перераспределения пластового давления после начала работы скважины или изменения темпа отбора жидкости из скважины.", "numbers": [], "question": null},
    {"key": "c2", "text": "Причина длительности — вязкость жидкости. При фильтрации вязкой жидкости в пласте возникают очень большие силы сопротивления.", "kind": "inference", "unit_id": "u-475-e20d95", "page": 475, "quote": "Это связано с тем, что при фильтрации вязкой жидкости в пласте возникают очень большие силы сопротивления.", "numbers": [], "question": null},
    {"key": "c3", "text": "Чем больше проницаемость, тем быстрее идут неустановившиеся процессы.", "kind": "inference", "unit_id": "u-475-e20d95", "page": 475, "quote": "Неустановившиеся процессы протекают тем быстрее, чем больше коэффициент проницаемости", "numbers": [], "question": null},
    {"key": "c4", "text": "Чем больше вязкость жидкости и коэффициенты объёмной упругости жидкости и скелета пласта, тем медленнее идут неустановившиеся процессы.", "kind": "inference", "unit_id": "u-475-e20d95", "page": 475, "quote": "и тем медленнее, чем больше вязкость жидкости $\\mu$ и коэффициенты объемной упругости жидкости $\\beta_\\text{ж}$ и твердого скелета пласта $\\beta_\\text{с}$.", "numbers": [], "question": null}
  ],
  "mechanism": [
    {"text": "Давление в пласте после пуска скважины или смены дебита выравнивается не сразу. Процесс растягивается во времени.", "claims": ["c1"], "hypothesis": false},
    {"text": "Главная причина задержки — вязкость жидкости. Вязкая жидкость при фильтрации создаёт большие силы сопротивления.", "claims": ["c2"], "hypothesis": false},
    {"text": "Скорость процесса задаётся тремя свойствами: проницаемостью, вязкостью и упругостью жидкости и скелета пласта.", "claims": ["c3", "c4"], "hypothesis": false},
    {"text": "Проницаемость ускоряет процесс. Вязкость и упругие коэффициенты жидкости и скелета замедляют его.", "claims": ["c3", "c4"], "hypothesis": false},
    {"text": "Почему упругие коэффициенты замедляют процесс: чем сильнее сжимаются жидкость и скелет, тем больше объём, который нужно сжать, прежде чем давление заметно сменится.", "claims": [], "hypothesis": true}
  ],
  "practice": [
    {"text": "Специалист смотрит, как долго давление перераспределяется после пуска скважины или смены темпа отбора.", "claims": ["c1"], "hypothesis": false},
    {"text": "Длительность перераспределения давления — характерный признак упругого режима.", "claims": ["c1"], "hypothesis": false},
    {"text": "Чтобы понять, почему процесс медленный, специалист проверяет проницаемость, вязкость и упругие коэффициенты.", "claims": [], "hypothesis": true}
  ],
  "nuances": [
    {"text": "Текст говорит о длительности качественно: процесс быстрее или медленнее. Числового порога времени в тексте нет.", "claims": [], "hypothesis": false},
    {"text": "Вязкость названа причиной задержки. Упругие коэффициенты тоже названы как замедлители, но их относительный вклад в тексте не сравнивается.", "claims": ["c2", "c4"], "hypothesis": false},
    {"text": "Условие, при котором виден такой процесс: начало работы скважины или изменение темпа отбора жидкости.", "claims": ["c1"], "hypothesis": false}
  ],
  "deeper": [
    {"title": "Единый показатель скорости", "text": "В следующих разделах главы проницаемость, вязкость и упругие коэффициенты объединяются в один показатель скорости перераспределения давления.", "claims": [], "hypothesis": true}
  ],
  "procedure": [],
  "numbers_conditions": [
    {"text": "Скорость процесса растёт с ростом коэффициента проницаемости k.", "claims": ["c3"]},
    {"text": "Скорость процесса падает с ростом вязкости μ и коэффициентов объёмной упругости β_ж и β_с.", "claims": ["c4"]},
    {"text": "Числовых порогов времени и числовых значений коэффициентов в этом узле нет.", "claims": []}
  ],
  "terms_defined": [
    {"term": "вязкость", "term_en": "viscosity", "abbr": "μ", "definition": "Мера внутреннего трения жидкости: насколько сильно она сопротивляется течению. Общее определение, в тексте узла не раскрыто подробно.", "claims": []},
    {"term": "коэффициент объёмной упругости жидкости", "term_en": "fluid bulk compressibility coefficient", "abbr": "β_ж", "definition": "Показатель того, насколько заметно сжимается жидкость при изменении давления. Общее определение; в тексте узла обозначен β_ж.", "claims": []},
    {"term": "коэффициент объёмной упругости пласта", "term_en": "rock skeleton bulk compressibility coefficient", "abbr": "β_с", "definition": "Показатель того, насколько заметно сжимается твёрдый скелет пласта при изменении давления. В тексте узла обозначен β_с как коэффициент объёмной упругости твёрдого скелета пласта.", "claims": []}
  ],
  "terms_used": ["неустановившийся процесс", "пластовое давление", "дебит", "флюид", "упругий режим", "фильтрация", "скелет пласта", "коэффициент проницаемости", "силы сопротивления", "скважина", "пласт"],
  "formulas": [],
